with content as (
  select * from jsonb_to_recordset($content$[
    {"level":"A2","title":"The Five-Minute Clean-Up","body":"Mara shares a study table with her younger brother. Every afternoon, the table is covered with books, paper and pens. She often spends time looking for what she needs before she can begin her homework.\n\nOne day, Mara decides to try a five-minute clean-up after dinner. She returns books to the shelf, puts pens in a cup and throws away used paper. Then she prepares the notebook she will need the next morning.\n\nThe task feels small, but the result is useful. Mara starts her homework more quickly and argues less with her brother. He sees that the system helps both of them, so he begins to put his own things away too.\n\nAfter two weeks, cleaning takes less than five minutes because there is less to organise. Mara learns that a small action can prevent a bigger problem. She did not need a new desk or a complicated plan. She needed a simple routine that was easy to repeat.","summary_fr":"Mara range la table d'étude pendant cinq minutes chaque soir. Cette petite routine lui fait gagner du temps, réduit les disputes et devient plus facile avec la répétition.","translation_fr":"Mara partage une table d'étude avec son petit frère. Chaque après-midi, la table est couverte de livres, de feuilles et de stylos. Elle passe souvent du temps à chercher ce dont elle a besoin avant de pouvoir commencer ses devoirs.\n\nUn jour, Mara décide d'essayer cinq minutes de rangement après le dîner. Elle remet les livres sur l'étagère, place les stylos dans un pot et jette les feuilles utilisées. Ensuite, elle prépare le cahier dont elle aura besoin le lendemain matin.\n\nLa tâche semble petite, mais le résultat est utile. Mara commence ses devoirs plus rapidement et se dispute moins avec son frère. Il voit que ce système les aide tous les deux, alors il commence lui aussi à ranger ses affaires.\n\nAprès deux semaines, le rangement prend moins de cinq minutes parce qu'il y a moins de choses à organiser. Mara comprend qu'une petite action peut empêcher un problème plus important. Elle n'avait pas besoin d'un nouveau bureau ni d'un plan compliqué. Elle avait besoin d'une routine simple et facile à répéter.","knowledge_point":"L'apprenant découvre comment une petite routine régulière peut prévenir un problème et faciliter le travail quotidien.","vocabulary":[{"word":"share","part_of_speech":"verb","translation_fr":"partager","definition":"To use something together with another person.","example":"Mara shares a table with her brother."},{"word":"covered","part_of_speech":"adjective","translation_fr":"couvert","definition":"Having things spread over a surface.","example":"The table is covered with books."},{"word":"look for","part_of_speech":"phrasal verb","translation_fr":"chercher","definition":"To try to find something.","example":"She looks for her notebook."},{"word":"throw away","part_of_speech":"phrasal verb","translation_fr":"jeter","definition":"To put something you do not need in the rubbish.","example":"She throws away used paper."},{"word":"argue","part_of_speech":"verb","translation_fr":"se disputer","definition":"To speak angrily because you disagree.","example":"Mara argues less with her brother."},{"word":"prevent","part_of_speech":"verb","translation_fr":"empêcher","definition":"To stop a problem from happening.","example":"A small action can prevent a bigger problem."},{"word":"complicated","part_of_speech":"adjective","translation_fr":"compliqué","definition":"Difficult to understand or do.","example":"She does not need a complicated plan."},{"word":"repeat","part_of_speech":"verb","translation_fr":"répéter","definition":"To do the same action again.","example":"The routine is easy to repeat."}],"questions":[{"type":"mcq","question":"Who shares the study table with Mara?","options":["Her younger brother","Her teacher","Her cousin","Her friend"],"answer":"Her younger brother","explanation_fr":"Mara partage la table avec son petit frère."},{"type":"mcq","question":"When does Mara clean the table?","options":["After dinner","Before breakfast","At midnight","Only on Monday"],"answer":"After dinner","explanation_fr":"Elle range la table après le dîner."},{"type":"mcq","question":"Where does she put the pens?","options":["In a cup","Under the table","In her bag","On the floor"],"answer":"In a cup","explanation_fr":"Elle place les stylos dans un pot."},{"type":"mcq","question":"What does she prepare for the next morning?","options":["Her notebook","Her lunch","Her shoes","Her brother's bed"],"answer":"Her notebook","explanation_fr":"Elle prépare le cahier nécessaire le lendemain matin."},{"type":"mcq","question":"What changes after two weeks?","options":["Cleaning takes less than five minutes","The desk disappears","Mara stops studying","Her brother buys a new table"],"answer":"Cleaning takes less than five minutes","explanation_fr":"Le rangement devient plus rapide parce qu'il y a moins à organiser."},{"type":"mcq","question":"Why does Mara's brother begin to organise his things?","options":["He sees that the system helps both of them","Mara gives him money","His teacher requires it","He wants a new desk"],"answer":"He sees that the system helps both of them","explanation_fr":"Il constate que ce système est utile à tous les deux."},{"type":"mcq","question":"What is the main lesson of the story?","options":["A small repeated action can prevent a bigger problem","Only new furniture solves problems","Cleaning must take several hours","A complicated plan is always best"],"answer":"A small repeated action can prevent a bigger problem","explanation_fr":"L'histoire montre l'utilité d'une petite action régulière."},{"type":"true_false","question":"Mara needs a complicated plan.","options":["True","False"],"answer":"False","explanation_fr":"Elle a besoin d'une routine simple, pas d'un plan compliqué."},{"type":"true_false","question":"The clean-up helps Mara begin her homework more quickly.","options":["True","False"],"answer":"True","explanation_fr":"Le texte indique qu'elle commence ses devoirs plus rapidement."},{"type":"open","question":"What five-minute routine could make your day easier?","options":[],"answer":"I can spend five minutes preparing my study table and the things I need for tomorrow.","explanation_fr":"La réponse doit décrire une routine courte, précise et utile."}],"grammar":[{"point":"Present simple for routines","explanation_fr":"Le présent simple décrit des actions habituelles. Avec she, le verbe prend généralement un s.","example":"She returns books to the shelf."},{"point":"Comparative with less","explanation_fr":"Less suivi d'un nom indénombrable exprime une quantité plus faible.","example":"There is less to organise."}],"discussion":["What small routine helps you study or work?","Why do simple plans sometimes work better than complicated plans?","Who could share a useful routine with you?"]},
    {"level":"B1","title":"A Small Garden, One Useful Lesson","body":"When Alain moved into a new home, he wanted to grow vegetables beside the house. On his first free Saturday, he bought many plants and worked for several hours. He felt proud, but he had not thought about the coming week. His work was busy, and he soon forgot to water the plants. Several of them died.\n\nAlain decided to begin again with a smaller space. He planted only a few vegetables and chose a simple time to care for them. Every morning, before leaving for work, he spent ten minutes checking the soil and removing weeds. He kept his watering can near the door so that he would remember the task.\n\nThe smaller garden did not look impressive at first. However, Alain could take care of it even during difficult weeks. The plants grew steadily, and he learned to observe small changes in their leaves. When a problem appeared, he responded before it became serious.\n\nHis first attempt had depended on one burst of energy. His second attempt depended on regular attention. Alain discovered that a modest project can produce a better result when its daily demands match the time you really have. Starting smaller allowed him to continue longer.","summary_fr":"Après un premier jardin trop ambitieux, Alain recommence avec quelques plantes et dix minutes d'attention chaque matin. Ce projet modeste devient durable parce qu'il correspond à son temps disponible.","translation_fr":"Quand Alain a emménagé dans une nouvelle maison, il a voulu faire pousser des légumes à côté de la maison. Lors de son premier samedi libre, il a acheté beaucoup de plantes et travaillé pendant plusieurs heures. Il était fier, mais il n'avait pas pensé à la semaine à venir. Son travail était prenant et il a vite oublié d'arroser les plantes. Plusieurs sont mortes.\n\nAlain a décidé de recommencer avec un espace plus petit. Il a planté seulement quelques légumes et choisi un moment simple pour s'en occuper. Chaque matin, avant de partir au travail, il passait dix minutes à vérifier la terre et à retirer les mauvaises herbes. Il gardait son arrosoir près de la porte pour ne pas oublier la tâche.\n\nLe petit jardin ne semblait pas impressionnant au début. Cependant, Alain pouvait s'en occuper même pendant les semaines difficiles. Les plantes poussaient régulièrement et il a appris à observer de petits changements dans leurs feuilles. Quand un problème apparaissait, il réagissait avant qu'il ne devienne grave.\n\nSa première tentative dépendait d'un élan d'énergie. Sa deuxième tentative dépendait d'une attention régulière. Alain a découvert qu'un projet modeste peut donner un meilleur résultat lorsque ses exigences quotidiennes correspondent au temps dont on dispose réellement. Commencer plus petit lui a permis de continuer plus longtemps.","knowledge_point":"L'apprenant comprend qu'un projet modeste et entretenu régulièrement peut être plus durable qu'un grand effort isolé.","vocabulary":[{"word":"grow","part_of_speech":"verb","translation_fr":"cultiver, pousser","definition":"To develop and become larger, or to help plants develop.","example":"He wanted to grow vegetables."},{"word":"water","part_of_speech":"verb","translation_fr":"arroser","definition":"To give water to plants.","example":"He forgot to water the plants."},{"word":"soil","part_of_speech":"noun","translation_fr":"terre, sol","definition":"The material in which plants grow.","example":"He checks the soil every morning."},{"word":"weeds","part_of_speech":"noun","translation_fr":"mauvaises herbes","definition":"Unwanted plants growing among other plants.","example":"He removes weeds from the garden."},{"word":"watering can","part_of_speech":"noun","translation_fr":"arrosoir","definition":"A container used to pour water on plants.","example":"His watering can is near the door."},{"word":"steadily","part_of_speech":"adverb","translation_fr":"régulièrement","definition":"In a gradual and continuous way.","example":"The plants grew steadily."},{"word":"attempt","part_of_speech":"noun","translation_fr":"tentative","definition":"An effort to do something.","example":"His second attempt was more realistic."},{"word":"modest","part_of_speech":"adjective","translation_fr":"modeste","definition":"Not very large or ambitious.","example":"A modest project can be easier to maintain."}],"questions":[{"type":"mcq","question":"What did Alain want to grow?","options":["Vegetables","Flowers for a shop","Trees for timber","Rice in a field"],"answer":"Vegetables","explanation_fr":"Alain voulait cultiver des légumes près de sa maison."},{"type":"mcq","question":"Why did several plants die?","options":["He forgot to water them","He watered them every morning","The garden was too small","He removed too many weeds"],"answer":"He forgot to water them","explanation_fr":"Son travail était prenant et il a oublié d'arroser les plantes."},{"type":"mcq","question":"How did he change his second project?","options":["He used a smaller space","He bought more plants","He worked only on Saturday","He stopped checking the soil"],"answer":"He used a smaller space","explanation_fr":"La deuxième tentative utilise un espace plus petit et quelques légumes."},{"type":"mcq","question":"When did Alain care for the second garden?","options":["Every morning before work","Every Saturday at noon","Only during holidays","Every evening after midnight"],"answer":"Every morning before work","explanation_fr":"Il consacrait dix minutes chaque matin avant le travail."},{"type":"mcq","question":"Why did he keep the watering can near the door?","options":["To remember the task","To hide it from neighbours","To water the floor","To sell it later"],"answer":"To remember the task","explanation_fr":"L'arrosoir visible servait de rappel."},{"type":"mcq","question":"What did regular observation help him do?","options":["Respond before problems became serious","Make the garden impressive immediately","Avoid all plant problems","Work fewer hours at his job"],"answer":"Respond before problems became serious","explanation_fr":"Il remarquait les changements et réagissait tôt."},{"type":"mcq","question":"What made the second attempt more successful?","options":["Regular attention suited to his available time","One long burst of energy","A larger number of plants","A perfect week without work"],"answer":"Regular attention suited to his available time","explanation_fr":"Le deuxième projet reposait sur une attention régulière et réaliste."},{"type":"true_false","question":"The smaller garden looked impressive immediately.","options":["True","False"],"answer":"False","explanation_fr":"Le texte précise qu'il ne semblait pas impressionnant au début."},{"type":"true_false","question":"Starting smaller helped Alain continue longer.","options":["True","False"],"answer":"True","explanation_fr":"C'est la conclusion explicite du texte."},{"type":"open","question":"Which project could you make smaller and easier to continue?","options":[],"answer":"I could begin with a smaller daily target that matches my available time, then maintain it regularly.","explanation_fr":"La réponse doit proposer une version réaliste et durable d'un projet."}],"grammar":[{"point":"Past perfect for an earlier action","explanation_fr":"Le past perfect situe une action avant un autre événement du passé.","example":"He had not thought about the coming week."},{"point":"So that for purpose","explanation_fr":"So that introduit le but recherché par une action.","example":"He kept his watering can near the door so that he would remember the task."}],"discussion":["Why can a modest project be easier to maintain?","Describe a time when starting smaller could have helped you.","How do visible reminders support regular action?"]},
    {"level":"B2","title":"The Compounding Effect of Small Actions","body":"Small actions are easy to underestimate because their immediate results are often modest. Reading one page does not make you an expert, and saving a small amount does not create financial security overnight. Yet the value of an action is not limited to what it produces today. Repetition can create skills, records and opportunities that make future action easier.\n\nConsider two people learning English. The first waits for a free afternoon and studies intensely once every few weeks. The second reviews ten words each morning and writes one sentence with them. Neither approach guarantees success, but the second creates more regular contact with the language. It also produces a useful record: after several weeks, the learner can see which words return often and which mistakes need attention.\n\nSmall actions can also reveal information. A short experiment shows whether a routine fits your schedule. If it fails, you can adjust it without abandoning the whole goal. A large plan, by contrast, may require so much preparation that you delay starting. The cost of testing it is higher, and the feedback arrives later.\n\nHowever, repetition alone is not enough. Repeating an ineffective method merely makes that method more familiar. Useful small actions need a direction and occasional review. You should ask whether the action still serves the goal and whether the result suggests a better approach.\n\nThe real strength of small steps is therefore not magic. It is their ability to make progress visible, reduce the cost of beginning and provide frequent feedback. A modest action becomes powerful when it is repeated thoughtfully and improved when necessary.","summary_fr":"Les petites actions facilitent le démarrage, rendent les progrès visibles et fournissent des retours fréquents. Leur efficacité dépend toutefois d'une direction claire et d'ajustements réguliers.","translation_fr":"Il est facile de sous-estimer les petites actions parce que leurs résultats immédiats sont souvent modestes. Lire une page ne fait pas de vous un expert et économiser une petite somme ne crée pas une sécurité financière du jour au lendemain. Pourtant, la valeur d'une action ne se limite pas à ce qu'elle produit aujourd'hui. La répétition peut créer des compétences, des traces et des occasions qui facilitent les actions futures.\n\nPrenons deux personnes qui apprennent l'anglais. La première attend un après-midi libre et étudie intensément une fois toutes les quelques semaines. La deuxième révise dix mots chaque matin et écrit une phrase avec ces mots. Aucune méthode ne garantit le succès, mais la deuxième crée un contact plus régulier avec la langue. Elle produit aussi une trace utile : après plusieurs semaines, l'apprenant peut voir quels mots reviennent souvent et quelles erreurs demandent une attention particulière.\n\nLes petites actions peuvent également révéler des informations. Une courte expérience montre si une routine convient à votre emploi du temps. Si elle échoue, vous pouvez l'ajuster sans abandonner tout l'objectif. Un grand projet, au contraire, peut exiger tellement de préparation que vous retardez le départ. Le coût de l'essai est plus élevé et le retour arrive plus tard.\n\nCependant, la répétition seule ne suffit pas. Répéter une méthode inefficace rend simplement cette méthode plus familière. Les petites actions utiles ont besoin d'une direction et d'un bilan occasionnel. Il faut se demander si l'action sert toujours l'objectif et si le résultat suggère une meilleure approche.\n\nLa véritable force des petits pas n'est donc pas magique. Elle réside dans leur capacité à rendre les progrès visibles, à réduire le coût du démarrage et à fournir des retours fréquents. Une action modeste devient puissante lorsqu'elle est répétée avec réflexion et améliorée si nécessaire.","knowledge_point":"L'apprenant analyse les conditions qui rendent les petites actions efficaces : régularité, retour d'expérience, direction et ajustement.","vocabulary":[{"word":"underestimate","part_of_speech":"verb","translation_fr":"sous-estimer","definition":"To think that something has less value or importance than it really has.","example":"Small actions are easy to underestimate."},{"word":"overnight","part_of_speech":"adverb","translation_fr":"du jour au lendemain","definition":"Very quickly, or during one night.","example":"A small saving does not create security overnight."},{"word":"intensely","part_of_speech":"adverb","translation_fr":"intensément","definition":"With a lot of effort or concentration.","example":"She studies intensely once every few weeks."},{"word":"review","part_of_speech":"verb","translation_fr":"réviser, examiner","definition":"To study something again or examine it carefully.","example":"He reviews ten words each morning."},{"word":"feedback","part_of_speech":"noun","translation_fr":"retour, retour d'expérience","definition":"Information about how well something is working.","example":"A small experiment provides early feedback."},{"word":"abandon","part_of_speech":"verb","translation_fr":"abandonner","definition":"To stop doing something before it is finished.","example":"You can adjust a routine without abandoning the goal."},{"word":"ineffective","part_of_speech":"adjective","translation_fr":"inefficace","definition":"Not producing the result you want.","example":"Repeating an ineffective method is not enough."},{"word":"thoughtfully","part_of_speech":"adverb","translation_fr":"avec réflexion","definition":"In a careful and considered way.","example":"Repeat a modest action thoughtfully."}],"questions":[{"type":"mcq","question":"Why are small actions easy to underestimate?","options":["Their immediate results are often modest","They always cost too much","They cannot be repeated","They produce no information"],"answer":"Their immediate results are often modest","explanation_fr":"Leur résultat immédiat modeste peut cacher leur valeur à long terme."},{"type":"mcq","question":"What does the second English learner do each morning?","options":["Reviews ten words and writes a sentence","Studies for a whole afternoon","Waits several weeks","Avoids writing"],"answer":"Reviews ten words and writes a sentence","explanation_fr":"Cette routine quotidienne associe révision et courte production."},{"type":"mcq","question":"What useful record does regular practice create?","options":["A view of frequent words and recurring mistakes","A guarantee of immediate fluency","A list of free afternoons","A reason to stop reviewing"],"answer":"A view of frequent words and recurring mistakes","explanation_fr":"Les traces permettent d'identifier les mots fréquents et les erreurs à traiter."},{"type":"mcq","question":"Why can a large plan delay starting?","options":["It may require too much preparation","It always provides early feedback","It is cheaper to test","It removes every risk"],"answer":"It may require too much preparation","explanation_fr":"Une préparation trop lourde peut repousser le début de l'action."},{"type":"mcq","question":"What can you do if a short experiment fails?","options":["Adjust the routine without abandoning the goal","Repeat it without thinking","Abandon every goal","Make the next experiment larger immediately"],"answer":"Adjust the routine without abandoning the goal","explanation_fr":"Une petite expérience permet un ajustement à faible coût."},{"type":"mcq","question":"What is the danger of repetition alone?","options":["It can make an ineffective method more familiar","It always reveals the best direction","It guarantees progress","It removes the need for review"],"answer":"It can make an ineffective method more familiar","explanation_fr":"La répétition ne corrige pas automatiquement une méthode inefficace."},{"type":"mcq","question":"Which combination makes a small action powerful?","options":["Thoughtful repetition and improvement when necessary","Repetition without direction","A large initial cost and delayed feedback","A perfect result on the first day"],"answer":"Thoughtful repetition and improvement when necessary","explanation_fr":"La conclusion associe répétition réfléchie et amélioration."},{"type":"true_false","question":"The text claims that every small action guarantees success.","options":["True","False"],"answer":"False","explanation_fr":"Le texte refuse cette garantie et insiste sur la direction et le bilan."},{"type":"true_false","question":"Small experiments can provide feedback earlier than large plans.","options":["True","False"],"answer":"True","explanation_fr":"Ils coûtent moins à tester et donnent un retour plus tôt."},{"type":"open","question":"Choose a small action and explain how you would review its usefulness.","options":[],"answer":"I can review ten words daily, then check each week whether I can use them in sentences and adjust the method if necessary.","explanation_fr":"La réponse doit associer une action précise, un indicateur de résultat et un ajustement possible."}],"grammar":[{"point":"Comparative structures","explanation_fr":"Les comparateurs higher et later comparent le coût et le moment du retour entre deux approches.","example":"The cost of testing it is higher, and the feedback arrives later."},{"point":"Whether for indirect questions","explanation_fr":"Whether introduit une question indirecte portant sur deux possibilités.","example":"Ask whether the action still serves the goal."}],"discussion":["Which small action gives you useful feedback?","How can you tell the difference between consistency and ineffective repetition?","Why do visible records support motivation?"]},
    {"level":"C1","title":"Why Small Actions Outlast Grand Gestures","body":"Grand gestures attract attention because they are visible, dramatic and easy to narrate. A person announces a complete transformation, purchases new equipment and works intensely for a weekend. Small actions rarely inspire the same excitement. Preparing tomorrow's notebook or practising a skill for ten minutes appears almost insignificant. Yet visibility is a poor measure of usefulness.\n\nThe practical advantage of a small action lies in its repeatability. It can survive an ordinary week, with its interruptions, obligations and fluctuations in energy. This does not mean that intensity has no value. A concentrated period of work may help someone complete a defined stage. Problems arise when the initial intensity becomes the only possible version of the behaviour. If a routine requires ideal conditions, its absence during a busy week can be interpreted as personal failure rather than faulty design.\n\nSmall actions also distribute learning over time. Instead of waiting for a final performance to discover a weakness, a person can observe the results of each modest attempt. This frequent feedback supports correction while the cost of change remains low. A short daily recording may reveal a pronunciation difficulty long before an important presentation. A brief weekly budget review may expose an unrealistic assumption before it affects several months of spending.\n\nNevertheless, smallness should not become an excuse for avoiding meaningful challenges. Some goals require difficult conversations, sustained study or decisions that cannot be divided into painless fragments. The purpose of a small step is to make movement possible, not to make the whole journey effortless.\n\nA mature approach therefore combines scale with direction. Choose an action small enough to repeat, important enough to matter and clear enough to evaluate. Then increase its scope when evidence suggests that you are ready. The objective is not to remain small forever, but to build a practice that can grow without collapsing under its own ambition.","summary_fr":"Les petites actions durent parce qu'elles sont répétables et fournissent des retours rapides. Elles ne suppriment pas les défis importants : elles créent une pratique capable de grandir sans devenir fragile.","translation_fr":"Les grandes actions attirent l'attention parce qu'elles sont visibles, spectaculaires et faciles à raconter. Une personne annonce une transformation complète, achète du nouveau matériel et travaille intensément pendant un week-end. Les petites actions suscitent rarement le même enthousiasme. Préparer le cahier du lendemain ou pratiquer une compétence pendant dix minutes semble presque insignifiant. Pourtant, la visibilité est un mauvais indicateur d'utilité.\n\nL'avantage pratique d'une petite action réside dans sa capacité à être répétée. Elle peut survivre à une semaine ordinaire, avec ses interruptions, ses obligations et ses variations d'énergie. Cela ne signifie pas que l'intensité n'a aucune valeur. Une période de travail concentré peut aider à terminer une étape définie. Les problèmes apparaissent lorsque l'intensité initiale devient la seule version possible du comportement. Si une routine exige des conditions idéales, son absence pendant une semaine chargée peut être interprétée comme un échec personnel plutôt que comme un défaut de conception.\n\nLes petites actions répartissent également l'apprentissage dans le temps. Au lieu d'attendre une performance finale pour découvrir une faiblesse, une personne peut observer les résultats de chaque modeste tentative. Ce retour fréquent permet de se corriger tant que le coût du changement reste faible. Un court enregistrement quotidien peut révéler une difficulté de prononciation bien avant une présentation importante. Un bref bilan budgétaire hebdomadaire peut exposer une hypothèse irréaliste avant qu'elle n'affecte plusieurs mois de dépenses.\n\nNéanmoins, la petitesse ne doit pas devenir une excuse pour éviter les défis significatifs. Certains objectifs exigent des conversations difficiles, une étude soutenue ou des décisions qui ne peuvent pas être divisées en fragments indolores. Le but d'un petit pas est de rendre le mouvement possible, pas de rendre tout le parcours sans effort.\n\nUne approche mature associe donc l'échelle et la direction. Choisissez une action assez petite pour être répétée, assez importante pour compter et assez claire pour être évaluée. Augmentez ensuite sa portée lorsque les résultats indiquent que vous êtes prêt. L'objectif n'est pas de rester petit pour toujours, mais de construire une pratique capable de grandir sans s'effondrer sous sa propre ambition.","knowledge_point":"L'apprenant développe une réflexion nuancée sur la régularité, l'intensité, le retour d'expérience et la progression des défis.","vocabulary":[{"word":"grand gesture","part_of_speech":"noun phrase","translation_fr":"grande action spectaculaire","definition":"A noticeable action intended to make a strong impression.","example":"Grand gestures attract attention."},{"word":"insignificant","part_of_speech":"adjective","translation_fr":"insignifiant","definition":"Too small or unimportant to seem worth considering.","example":"Ten minutes may appear insignificant."},{"word":"repeatability","part_of_speech":"noun","translation_fr":"caractère répétable","definition":"The quality of being possible to do again regularly.","example":"The advantage of a small action lies in its repeatability."},{"word":"fluctuation","part_of_speech":"noun","translation_fr":"variation","definition":"A repeated change in level or amount.","example":"Ordinary weeks include fluctuations in energy."},{"word":"faulty","part_of_speech":"adjective","translation_fr":"défectueux, mal conçu","definition":"Not working correctly or not designed well.","example":"The problem may be faulty design rather than personal failure."},{"word":"assumption","part_of_speech":"noun","translation_fr":"hypothèse","definition":"Something accepted as true without certain proof.","example":"A review may expose an unrealistic assumption."},{"word":"sustained","part_of_speech":"adjective","translation_fr":"soutenu","definition":"Continuing for a long time.","example":"Some goals require sustained study."},{"word":"scope","part_of_speech":"noun","translation_fr":"portée, ampleur","definition":"The size or extent of an activity.","example":"Increase the action's scope when you are ready."}],"questions":[{"type":"mcq","question":"Why do grand gestures attract attention?","options":["They are visible, dramatic and easy to narrate","They are always repeatable","They require no equipment","They provide the fastest feedback"],"answer":"They are visible, dramatic and easy to narrate","explanation_fr":"Ces trois caractéristiques expliquent leur attrait selon le premier paragraphe."},{"type":"mcq","question":"What is the practical advantage of a small action?","options":["Its repeatability during ordinary weeks","Its dramatic appearance","Its need for ideal conditions","Its freedom from evaluation"],"answer":"Its repeatability during ordinary weeks","explanation_fr":"La petite action peut être maintenue malgré les interruptions et obligations."},{"type":"mcq","question":"When can concentrated work be useful?","options":["When it helps complete a defined stage","When it becomes the only acceptable routine","When it removes the need for feedback","When it guarantees a transformation"],"answer":"When it helps complete a defined stage","explanation_fr":"Le texte reconnaît la valeur de l'intensité pour une étape précise."},{"type":"mcq","question":"How can a busy week expose faulty routine design?","options":["A routine requiring ideal conditions may become impossible","A repeatable routine always collapses","Small actions prevent every interruption","Energy remains constant throughout the week"],"answer":"A routine requiring ideal conditions may become impossible","explanation_fr":"Une routine trop dépendante de conditions idéales révèle sa fragilité."},{"type":"mcq","question":"Why is frequent feedback valuable?","options":["It supports correction while change is still inexpensive","It makes every weakness disappear","It replaces meaningful challenges","It delays discovery until the final performance"],"answer":"It supports correction while change is still inexpensive","explanation_fr":"Les essais modestes permettent de corriger tôt et à faible coût."},{"type":"mcq","question":"What limitation of small steps does the text acknowledge?","options":["They cannot remove every meaningful challenge","They are always insignificant","They prevent long-term growth","They eliminate the need for direction"],"answer":"They cannot remove every meaningful challenge","explanation_fr":"Certains objectifs exigent des efforts ou décisions qui ne deviennent pas indolores."},{"type":"mcq","question":"Which action best follows the final advice?","options":["Repeatable, meaningful and clear enough to evaluate","Small, vague and impossible to measure","Dramatic, expensive and dependent on ideal conditions","Ambitious, permanent and never reviewed"],"answer":"Repeatable, meaningful and clear enough to evaluate","explanation_fr":"Ces trois critères figurent dans le dernier paragraphe."},{"type":"true_false","question":"The author believes that people should remain at the same small scale forever.","options":["True","False"],"answer":"False","explanation_fr":"L'objectif est de construire une pratique qui peut grandir."},{"type":"true_false","question":"Visibility alone is presented as a reliable measure of usefulness.","options":["True","False"],"answer":"False","explanation_fr":"Le texte affirme que la visibilité est un mauvais indicateur d'utilité."},{"type":"open","question":"Design a small action that could grow without becoming fragile.","options":[],"answer":"I can begin with ten minutes of recorded speaking practice, review one difficulty each week, and increase the duration only when the routine remains manageable during busy weeks.","explanation_fr":"La réponse doit inclure une action répétable, un retour mesurable et une progression conditionnée par les résultats."}],"grammar":[{"point":"Comparative and evaluative structures","explanation_fr":"Les structures assez... pour et too... to permettent d'évaluer si une action est adaptée à un but.","example":"Choose an action small enough to repeat, important enough to matter and clear enough to evaluate."},{"point":"Contrast with nevertheless","explanation_fr":"Nevertheless introduit une restriction ou une opposition à l'idée précédente.","example":"Nevertheless, smallness should not become an excuse for avoiding meaningful challenges."}],"discussion":["When is intense work more useful than a small daily action?","How can you prevent a small step from becoming an avoidance strategy?","What evidence would tell you that a practice is ready to grow?"]}
  ]$content$::jsonb) as x(
    level public.rw_level, title text, body text, summary_fr text, translation_fr text,
    knowledge_point text, vocabulary jsonb, questions jsonb, grammar jsonb, discussion jsonb
  )
)
insert into public.rw_lessons (
  session_id, level, title, body, word_count, summary_fr, translation_fr, knowledge_point,
  vocabulary, questions, grammar, discussion, mention, status, content_type, rights_status,
  published_at
)
select s.id, c.level, c.title, c.body,
  cardinality(regexp_split_to_array(btrim(c.body), '[[:space:]]+')),
  c.summary_fr, c.translation_fr, c.knowledge_point, c.vocabulary, c.questions,
  c.grammar, c.discussion, 'original', 'published', 'original text',
  'Texte original OpenDoorsClass', now()
from content c
join public.rw_weeks w on w.week_number = 3
join public.rw_sessions s on s.week_id = w.id and s.day_index = 6
on conflict (session_id, level) do update set
  title = excluded.title, body = excluded.body, word_count = excluded.word_count,
  summary_fr = excluded.summary_fr, translation_fr = excluded.translation_fr,
  knowledge_point = excluded.knowledge_point, vocabulary = excluded.vocabulary,
  questions = excluded.questions, grammar = excluded.grammar, discussion = excluded.discussion,
  mention = 'original', status = 'published', content_type = 'original text',
  rights_status = 'Texte original OpenDoorsClass', published_at = coalesce(rw_lessons.published_at, now())
where rw_lessons.status <> 'published';

do $$
declare invalid_count integer;
begin
  select count(*) into invalid_count
  from public.rw_lessons l
  join public.rw_sessions s on s.id = l.session_id
  join public.rw_weeks w on w.id = s.week_id
  where w.week_number = 3 and s.day_index = 6
    and (l.status <> 'published' or jsonb_array_length(l.questions) <> 10
      or jsonb_array_length(l.vocabulary) < 8 or jsonb_array_length(l.grammar) <> 2
      or jsonb_array_length(l.discussion) <> 3 or l.body = '' or l.translation_fr = '');
  if invalid_count <> 0 then raise exception 'Validation impossible: % leçons incomplètes', invalid_count; end if;
end $$;